// Routes the monitor page, status JSON, history request or an unknown path.
// In: an authenticated GET with the optional route parameter `view`.
// Out: exactly one of PAGE, STATUS, HISTORY or ERROR.
var view = msg.req && msg.req.params && msg.req.params.view;

if (!view) {
  return [msg, null, null, null];
}
if (view === 'status') {
  return [null, msg, null, null];
}
if (view === 'history') {
  return [null, null, msg, null];
}

msg.statusCode = 404;
msg.headers = {
  'content-type': 'application/json'
};
msg.payload = {
  error: 'unknown monitor endpoint'
};
return [null, null, null, msg];

// Builds a JSON snapshot of the small global run-status records.
// In: an authenticated status request.
// Out: JSON with a derived STUCK state after 30 minutes without a checkpoint.
var STUCK_AFTER_MS = 30 * 60 * 1000;
var now = Date.now();
var keys = [
  'runStatus_sih-hull',
  'runStatus_rpt-hull',
  'runStatus_pbi-report',
  'runStatus_pbi-listener'
];
var flows = {};

function active(status) {
  if (status.state === 'running' || status.state === 'queued') {
    return true;
  }
  var days = status.days || {};
  return Object.keys(days).some(function (day) {
    return days[day].state === 'running' ||
      days[day].state === 'queued';
  });
}

function snapshot(key) {
  var stored = glob.get(key);
  if (!stored || typeof stored !== 'object') {
    return {
      state: 'not started'
    };
  }

  var copy = JSON.parse(JSON.stringify(stored));
  var running = active(copy);
  copy.state = copy.state || (running ? 'running' : 'idle');
  var beat = Date.parse(copy.lastBeatAt || copy.startedAt || '');
  if (running && isFinite(beat) && now - beat > STUCK_AFTER_MS) {
    copy.state = 'STUCK';
    copy.stuck = true;
    Object.keys(copy.days || {}).forEach(function (day) {
      var item = copy.days[day];
      if (item.state === 'running' || item.state === 'queued') {
        item.state = 'STUCK';
      }
    });
  } else {
    copy.stuck = false;
  }
  return copy;
}

keys.forEach(function (key) {
  flows[key.replace('runStatus_', '')] = snapshot(key);
});
var cfg = glob.get('cfg');
flows.config = cfg && cfg.platform && Array.isArray(cfg.sites) ?
  {
    state: 'ready',
    platform: cfg.platform,
    sites: cfg.sites.length
  } : {
    state: 'unavailable'
  };

msg.statusCode = 200;
msg.headers = {
  'content-type': 'application/json; charset=utf-8',
  'cache-control': 'no-store'
};
msg.payload = {
  generatedAt: new Date(now).toISOString(),
  stuckAfterMs: STUCK_AFTER_MS,
  flows: flows
};
return msg;

// Validates a history query and builds the one-month data-lake folder path.
// In: query.flow and query.month from the authenticated history request.
// Out: the list-objects request, or an explicit 400/503 JSON response.
var FLOWS = ['sih-hull', 'rpt-hull', 'pbi-report'];
var query = msg.req && msg.req.query ? msg.req.query : {};
var flowName = String(query.flow || '');
var month = String(query.month || '');

function refuse(code, reason) {
  msg.statusCode = code;
  msg.headers = {
    'content-type': 'application/json'
  };
  msg.payload = {
    error: reason
  };
  return [null, msg];
}

if (FLOWS.indexOf(flowName) === -1) {
  return refuse(400, 'flow must be a known report log');
}
if (!/^\d{4}-(0[1-9]|1[0-2])$/.test(month)) {
  return refuse(400, 'month must be YYYY-MM');
}

var cfg = glob.get('cfg');
if (!cfg || !cfg.root) {
  return refuse(503, 'Config is not available');
}

msg.historyFlow = flowName;
msg.historyMonth = month;
msg.historyFolder = cfg.root + '/logs/' + flowName + '/';
msg.historyName = 'log_' + month + '.csv';
msg.path = msg.historyFolder;
return [msg, null];

// Finds the requested month file in the listed log folder.
// In: msg.payload = list objects result; msg.historyName = exact filename.
// Out: read object, 404 when absent, or 502 for an invalid list response.
if (!Array.isArray(msg.payload)) {
  msg.statusCode = 502;
  msg.headers = {
    'content-type': 'application/json'
  };
  msg.payload = {
    error: 'the data lake did not return a history folder list'
  };
  return [null, null, msg];
}

var found = msg.payload.filter(function (item) {
  return String(item.key || '').split('/').pop() === msg.historyName;
})[0];

if (!found) {
  msg.statusCode = 404;
  msg.headers = {
    'content-type': 'application/json'
  };
  msg.payload = {
    error: 'history file not found',
    flow: msg.historyFlow,
    month: msg.historyMonth
  };
  return [null, msg, null];
}

msg.path = found.key;
return [msg, null, null];

// Parses one quoted CSV log file and returns its newest 200 rows as JSON.
// In: msg.payload = the CSV text from the data lake read-object node.
// Out: JSON rows, or an explicit 502 for an unusable file.
var MAX_ROWS = 200;
var text = msg.payload;

if (typeof text !== 'string') {
  msg.statusCode = 502;
  msg.headers = {
    'content-type': 'application/json'
  };
  msg.payload = {
    error: 'the data lake did not return log text'
  };
  return msg;
}

var rows = [];
var row = [];
var field = '';
var quoted = false;
for (var i = 0; i < text.length; i++) {
  var ch = text.charAt(i);
  if (ch === '"') {
    if (quoted && text.charAt(i + 1) === '"') {
      field += '"';
      i++;
    } else {
      quoted = !quoted;
    }
  } else if (ch === ',' && !quoted) {
    row.push(field);
    field = '';
  } else if (ch === '\n' && !quoted) {
    row.push(field.replace(/\r$/, ''));
    rows.push(row);
    row = [];
    field = '';
  } else {
    field += ch;
  }
}
if (field || row.length) {
  row.push(field.replace(/\r$/, ''));
  rows.push(row);
}

var headers = rows.shift() || [];
if (headers.indexOf('ts_utc') === -1 ||
    headers.indexOf('message') === -1) {
  msg.statusCode = 502;
  msg.headers = {
    'content-type': 'application/json'
  };
  msg.payload = {
    error: 'the history file has an unexpected header'
  };
  return msg;
}

var entries = rows.filter(function (values) {
  return values.some(function (value) {
    return value !== '';
  });
}).map(function (values) {
  var entry = {};
  headers.forEach(function (header, index) {
    entry[header] = values[index] || '';
  });
  return entry;
});
var total = entries.length;
var recent = entries.slice(-MAX_ROWS);

msg.statusCode = 200;
msg.headers = {
  'content-type': 'application/json; charset=utf-8',
  'cache-control': 'no-store'
};
msg.payload = {
  flow: msg.historyFlow,
  month: msg.historyMonth,
  count: total,
  truncated: total - recent.length,
  rows: recent
};
return msg;

// Returns a safe, explicit error for monitor-node failures.
// In: a message from a catch node.
// Out: a generic JSON 502 without exposing request credentials.
node.status({
  fill: 'red',
  shape: 'ring',
  text: 'monitor request failed'
});
msg.statusCode = 502;
msg.headers = {
  'content-type': 'application/json'
};
msg.payload = {
  error: 'monitor request failed'
};
return msg;
